// 4-bit function, implemented as a Karnaugh map. Don't-care values (d) are
// filled with don't-care wires (w).
module TopModule (
    input [3:0] x,
    output      f
);
    wire [3:0] a = x[0] ^ x[1];
    wire [3:0] b = x[2] ^ x[3];
    wire [3:0] c = x[0] ^ x[2];
    wire [3:0] d = x[1] ^ x[3];
    wire [3:0] e = ~(x[0] ^ x[1] ^ x[2] ^ x[3]);
    wire [3:0] f_func = a & b & c & d | e;
    assign f = f_func;
endmodule

